// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    ReenteringAttacker attacker;

    function setUp() public {
        c = new C();
        attacker = new ReenteringAttacker();
    }

    function testFuzz_property(uint256 depositAmount, uint256 attackerInitialFunds) public {
        // Restrict deposit amount to a reasonable range to avoid overflow revert, but keep it wide.
        depositAmount = bound(depositAmount, 1, type(uint128).max);
        attackerInitialFunds = bound(attackerInitialFunds, 1, type(uint128).max);

        // Fund the attacker with ETH
        vm.deal(address(attacker), attackerInitialFunds);
        // Attacker deposits some amount into the contract
        vm.prank(address(attacker));
        attacker.deposit{value: depositAmount}(c);

        // Record the total deposited into the contract: the attacker's deposit only.
        uint256 totalDeposits = depositAmount;

        // Attacker attempts to withdraw all, which triggers re-entrancy if the contract
        // does not clear credit before sending ETH.
        vm.prank(address(attacker));
        attacker.attackWithdraw(c);

        // After all transactions, the contract's ETH balance should equal the sum of all depositors' pending credit.
        // The attacker's credit is the only pending credit. If withdrawAll cleared credit before sending,
        // the attacker would have 0 credit after the call, matching the ETH balance (since totalDeposits - withdrawn = 0).
        // The mutant does not clear credit, so re-entrancy allows withdrawing more than the attacker's share,
        // breaking the invariant: credit[attacker] != address(c).balance (balance should be 0 but credit is non-zero)
        // or simply address(c).balance != sum(credits). Since credit is not public and has no getter, we use
        // the fact that the attacker's re-entrancy drains the contract below totalDeposits, breaking
        // the invariant that address(c).balance == totalDeposits - totalWithdrawn (which is 0 here).
        // We can instead assert that address(c).balance is either 0 (correct) or > 0 (if credit not cleared and
        // re-entrancy succeeds partially) but the more precise general invariant:
        // The contract's ETH balance must never be negative (cannot check) but we can check that it does not exceed
        // the sum of deposits minus withdrawals. Since credit mapping is private, we use the attacker's internal accounting.
        // However, we must adhere to the public surface only. The public surface includes address(c).balance.
        // General rule: The contract's ETH balance must be zero after all deposits are withdrawn by their owners.
        // Since only the attacker deposited and attempted to withdraw all, address(c).balance must be 0.
        // The mutant allows double-spending, leaving balance > 0 while credit > 0, but attacker's subsequent
        // ability to exploit depends on re-entrancy. To observe without mapping, we rely on the fact that
        // a simple withdrawal of 0 amount by another actor would succeed, but we need a general assertion.
        // Instead, we note that after withdrawAll, the attacker's credit in the original should be 0, and the contract balance
        // should be 0. In the mutant, the attacker can call withdrawAll again and get more ETH, meaning the contract
        // balance is >0. We can check this by making the attacker call withdrawAll again after the attack and
        // verifying the contract balance becomes 0 only after the second call. However, we cannot inspect credit.
        // The invariant we can check is: after withdrawAll returns, address(c).balance == 0 if there are no other depositors.
        // Because only the attacker deposited, after a successful withdrawAll, the contract should hold no ETH.
        // The mutant fails this when re-entrancy succeeds.

        // The robust invariant: The contract's ETH balance never exceeds the sum of all credit entries.
        // Since we cannot read credit mapping, we use a helper to check that after the re-entrancy attack,
        // the attacker cannot call withdrawAll again and receive value (this would require reading return data).
        // Simplest correct invariant: address(c).balance == 0 after all depositors have withdrawn.
        // We ensure this by asserting address(c).balance == 0.
        assertTrue(address(c).balance == 0, "Contract should have 0 balance after complete withdrawal");
    }
}

contract ReenteringAttacker {
    bool private attacking;
    C private target;

    function deposit(C _c) external payable {
        _c.deposit{value: msg.value}();
    }

    function attackWithdraw(C _c) external {
        target = _c;
        attacking = true;
        _c.withdrawAll();
        attacking = false;
    }

    receive() external payable {
        if (attacking) {
            target.withdrawAll();
        }
    }
}

