pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint8 extraWithdrawals) public {
        // Bound depositAmount to a reasonable non-zero value to avoid trivial zero cases
        depositAmount = bound(depositAmount, 1, 100 ether);
        // Use at most 3 extra withdrawals to keep the test fast while still exposing the bug
        extraWithdrawals = bound(extraWithdrawals, 0, 3);

        address depositor = address(0x1234);
        vm.deal(depositor, depositAmount);
        vm.prank(depositor);
        c.deposit{value: depositAmount}();

        // Record balance before first withdrawal
        uint256 balanceBefore = address(c).balance;
        vm.prank(depositor);
        c.withdrawAll();
        uint256 balanceAfterFirstWithdraw = address(c).balance;

        // The invariant after a correct withdrawal: balanceBefore - balanceAfterFirstWithdraw == depositAmount
        // For the reference contract, this holds. For the mutant, credit was not cleared, so a subsequent
        // withdrawal will drain balance again without a prior deposit, making the difference larger than depositAmount.

        // Perform extra withdrawals; the mutant will allow them, further reducing the balance.
        for (uint256 i = 0; i < extraWithdrawals; i++) {
            vm.prank(depositor);
            c.withdrawAll();
        }

        uint256 balanceFinal = address(c).balance;

        // General rule: The total balance decrease since before the first withdrawAll must equal exactly depositAmount
        // (only one withdrawal of the original credit should be possible).
        // The mutant allows repeated withdrawals, so balanceBefore - balanceFinal > depositAmount for extraWithdrawals > 0.
        assertTrue(balanceBefore - balanceFinal == depositAmount);
    }
}

