pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 deposit1, uint256 deposit2, uint8 extraWithdrawals) public {
        // Bound deposits to a wide but safe range to avoid overflow
        deposit1 = bound(deposit1, 0, type(uint128).max);
        deposit2 = bound(deposit2, 0, type(uint128).max);
        extraWithdrawals = bound(extraWithdrawals, 0, 3);

        // Deploy an adversarial re-entrant caller that attempts to withdraw extra times
        Attacker attacker = new Attacker();

        // Fund the attacker with the first deposit amount
        vm.deal(address(attacker), deposit1);
        // Attacker deposits as user in C
        attacker.depositToC{value: deposit1}(address(c));

        // Fund a second user (Alice) and have her deposit
        address alice = address(0xABCD);
        vm.deal(alice, deposit2);
        vm.prank(alice);
        c.deposit{value: deposit2}();

        // Attacker invokes withdrawAll, which re-enters up to extraWithdrawals times
        uint256 attackerPreCredit = deposit1;
        uint256 aliceCredit = deposit2;
        uint256 totalCredit = attackerPreCredit + aliceCredit;

        // attacker.withdrawReentrant drives the withdrawAll call and may trigger re-entrancy
        attacker.withdrawReentrant(address(c), extraWithdrawals);

        // After all calls, the contract's ETH balance must be >= total user credit
        // Since re-entrancy re-credits the attacker, the bug allows balance to fall below total credit
        assertTrue(address(c).balance >= totalCredit);
    }
}

contract Attacker {
    uint8 public reentryCount;
    uint8 public targetReentries;
    address public targetC;

    function depositToC(address _c) external payable {
        C(_c).deposit{value: msg.value}();
    }

    function withdrawReentrant(address _c, uint8 _targetReentries) external {
        reentryCount = 0;
        targetReentries = _targetReentries;
        targetC = _c;
        C(_c).withdrawAll();
    }

    receive() external payable {
        if (reentryCount < targetReentries && targetC != address(0)) {
            reentryCount++;
            C(targetC).withdrawAll();
        }
    }
}

