import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint8 actors) public {
        // Restrict amount to a non-zero range to guarantee deposit
        amount = bound(amount, 1, 100 ether);
        // Use up to 5 distinct actors
        uint8 count = uint8(bound(actors, 1, 5));

        address[] memory depositors = new address[](count);
        uint256[] memory credits = new uint256[](count);

        for (uint8 i = 0; i < count; i++) {
            depositors[i] = address(uint160(uint256(keccak256(abi.encode(i, count, amount)))));
            vm.deal(depositors[i], amount);
            vm.prank(depositors[i]);
            c.deposit{value: amount}();
            credits[i] = amount;
