            vm.prank(depositors[i]);
            c.withdrawAll();
        }

        // Sum of all user credits after withdrawals
        uint256 totalCredits = 0;
        for (uint8 i = 0; i < count; i++) {
            totalCredits += c.credit(depositors[i]);
        }

        // Rule: recorded balance plus total outstanding credits equals actual ETH balance
        assertTrue(c.balance() + totalCredits == address(c).balance);
    }
