pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint96 amount, bool useReverter) public {
        // 1. Admissible domain: amount > 0 so withdrawAll actually transfers ETH
        vm.assume(amount > 0);

        // 2. Deploy an adversarial helper that always reverts on receive, to trigger a failed call
        //    (the buggy version requires !callResult, i.e., a failed external call, to succeed)
        address payable reverter = payable(address(new Reverter()));

        // Decide which actor will withdraw: either a normal EOA or the reverter contract.
        // The bug manifests when the external call fails (useReverter = true),
        // which the fuzzer can choose.
        address actor = useReverter ? reverter : address(0x1234);

        // Deposit `amount` ETH from actor, then record pre-state
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        uint256 creditBefore = c.credit(actor);
        uint256 balanceBefore = address(c).balance;

        // Execute withdrawAll as actor
        vm.prank(actor);
        // Catch whether c.withdrawAll() reverts
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        if (ok) {
            // WithdrawAll succeeded without reverting.
            // Reference C: this ONLY happens when the external call succeeds (callResult == true).
            // After success, credit[actor] must be 0 and the contract balance must have decreased
            // by the original credit.
            uint256 creditAfter = c.credit(actor);
            uint256 balanceAfter = address(c).balance;
            assertTrue(
                creditAfter == 0 && balanceAfter == balanceBefore - creditBefore
            );
            // The mutant: when callResult is true, require(!callResult) fails -> revert.
            // So the mutant NEVER reaches ok == true for any input where an EOA succeeds.
            // But when actor is the Reverter, callResult is false, require(!false) passes,
            // ok becomes true, BUT state is wrong: credit is zero, balance unchanged.
            // This violates the assertion, distinguishing the bug.
        }
        // If ok == false, both contracts revert (mutant reverts on true callResult; C may revert on false).
        // That path is not required to satisfy the assertion.
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}

